import torch,math
from hec_policy import mean_signal,COST

def paired_discrimination(nodes,pw,pred,mean,scale,c2):
 v=c2[:,2:]+nodes.new_tensor([1.,-1.,1.,-1.]);v=v/(v.square().sum(-1,keepdim=True)+1e-6).sqrt();projection=(((nodes-mean[:,None])/scale[:,None])*v[:,None]).sum(-1);lp=pw.clamp_min(1e-38).log();plus=(lp+projection).softmax(-1);minus=(lp-projection).softmax(-1);mp=(plus[:,None]*pred).sum(-1);mm=(minus[:,None]*pred).sum(-1);vp=(plus[:,None]*(pred-mp[:,:,None]).square()).sum(-1);vm=(minus[:,None]*(pred-mm[:,:,None]).square()).sum(-1);kl=(vp+vm+(mp-mm).square())/.5;sep=(mp-mm)/(.25+vp+vm).sqrt();semantic=torch.cat([torch.log1p(kl),sep,torch.log1p(vp*4),torch.log1p(vm*4)],-1);hp=(plus[...,None]*nodes).sum(1);hm=(minus[...,None]*nodes).sum(1);return semantic,plus,minus,hp,hm

def prospective_opportunity(nodes,pw,actions,c4,stage):
 # Systematic 8-point approximation of the existing 64-node belief;no prior restart.
 q=(torch.arange(8,device=nodes.device,dtype=nodes.dtype)+.5)/8;idx=torch.searchsorted(pw.cumsum(-1).contiguous(),q.expand(len(nodes),8).contiguous()).clamp_max(nodes.shape[1]-1);theta=nodes.gather(1,idx[...,None].expand(-1,-1,4));m=mean_signal(theta,actions);mu=m.mean(-1);var=.25+(m-mu[...,None]).square().mean(-1);offset=nodes.new_tensor([-math.sqrt(3),0.,math.sqrt(3)]);ow=nodes.new_tensor([1/6,2/3,1/6]);y=mu[:,:,None]+var.sqrt()[:,:,None]*offset;weights=(-2*(y[:,:,:,None]-m[:,:,None]).square()).softmax(-1);posterior_mean=torch.einsum('bpqn,bnd->bpqd',weights,theta);center=posterior_mean.reshape(len(nodes),3,3,2,2).mean(-2);v=c4[:,:2]+nodes.new_tensor([0.,1.]);v=v/(v.square().sum(-1,keepdim=True)+1e-6).sqrt();angle=math.pi*.5*c4[:,3];v2=torch.stack([v[:,0]*angle.cos()-v[:,1]*angle.sin(),v[:,0]*angle.sin()+v[:,1]*angle.cos()],-1);future=(center[:,:,:,None]+nodes.new_tensor([0.,1.,-1.])[None,None,None,:,None]*v2[:,None,None,None]).clamp(-4,4);repeat=theta[:,None,None].expand(-1,3,3,-1,-1).reshape(-1,8,4);m2=mean_signal(repeat,future.reshape(-1,3,2)).reshape(len(nodes),3,3,3,8);pm=(weights[:,:,:,None]*m2).sum(-1);pv=(weights[:,:,:,None]*(m2-pm[...,None]).square()).sum(-1);remaining=(29-stage).clamp_min(0).to(nodes.dtype)/29;op=(torch.log1p(4*pv)*ow[None,None,:,None]).sum(2)*remaining[:,None,None];immediate=(weights*(weights.clamp_min(1e-38).log()+math.log(8))).sum(-1);immediate=(immediate*ow).sum(-1);return torch.cat([op.flatten(1),immediate],-1)
